sys_variable_value.value:
(function execute(inputs, outputs) {
// ... code ...

var gr = new GlideRecord('x_1682115_vehicl_0_parking_management');
gr.addQuery('is_available',true);
gr.addQuery('assigned_to','');
gr.addQuery('vehicle_type',inputs.vType);
gr.query();

var count = 0;
var lot = '';

while(gr.next() && gr.hasNext())
{
    if(count < 1)
    {
        gr.assigned_to = inputs.vNumber;
        gr.is_available = false;
        lot = gr.parking_slot;
        gr.update();

        break;
    }
    count++;

}

if(lot != '')
{
    outputs.lot = lot;
    outputs.status = 'true';
}else{
    outputs.lot = lot;
    outputs.status = 'false';
}


})(inputs, outputs);

